firmware:
#include <ESP32Servo.h>

const int POT = 34;
const int SERVO = 18;
Servo servo;
unsigned long lastPrint = 0;

void setup() {
  Serial.begin(115200);
  pinMode(POT, INPUT);
  servo.attach(SERVO);
}

void loop() {
  int raw = analogRead(POT);
  int angle = map(raw, 0, 4095, 0, 180);
  servo.write(angle);
  if (millis() - lastPrint >= 500) {
    lastPrint = millis();
    Serial.print("ANGLE=");
    Serial.println(angle);
  }
  delay(50);
}
